from pathlib import Path
import re,json
out=Path('.work/vm-windows-variable-investigation-20261115');syms=json.loads((out/'symbols.json').read_text());report={}
def ins(p):
 rows=[]
 for l in p.read_text(encoding='utf8').splitlines():
  f=l.split('\t');m=re.match(r'\s*([0-9a-f]+):',f[0])
  if m and len(f)>=3 and f[2].strip():rows.append((int(m[1],16),f[2].strip()))
 return rows
def norm(rows,start,size):
 result=[]
 for a,s in rows:
  s=re.sub(r'\s*<[^>]+>','',s);s=re.sub(r'(?<=\s)([0-9a-f]{9,})(?=\s|$)',r'0x\1',s)
  def addr(m):
   n=int(m[0],16)
   return 'LOCAL+'+hex(n-start) if start<=n<start+size else ('EXTERNAL' if 0x140000000<=n<0x150000000 else m[0])
  result.append((a-start,re.sub(r'0x[0-9a-f]+',addr,s)))
 return result
for label in syms:
 sr=ins(out/f'{label}-symbols.asm');tr=ins(out/f'{label}-strip.asm');report[label]=[]
 for symbol in syms[label]['symbols']:
  a=int(symbol['address'],16);size=symbol['bytes'];body=[x for x in sr if a<=x[0]<a+size];prefix=norm(body[:16],a,size)
  hits=[i for i in range(len(tr)-16) if norm(tr[i:i+16],tr[i][0],size)==prefix];assert len(hits)==1,(label,symbol,len(hits));b=tr[hits[0]][0];tb=[x for x in tr if b<=x[0]<b+size]
  diffs=[{'symbol':x,'strip':y} for x,y in zip(norm(body,a,size),norm(tb,b,size)) if x!=y];row={**symbol,'strip_address':hex(b),'instruction_lines':len(body),'strip_instruction_lines':len(tb),'normalized_equal':not diffs and len(body)==len(tb),'differences':diffs};report[label].append(row)
  (out/f'{label}-{symbol["name"]}-strip.txt').write_text('\n'.join(f'{x:x}\t{s}' for x,s in tb)+'\n');print(label,symbol['name'],hex(b),size,len(body),'diffs',len(diffs))
(out/'loop-map.json').write_text(json.dumps(report,indent=2)+'\n')
